/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerSupportRoutes } from './support.controller.ts';

/** Registers the feature routes. */
export function registerSupportModule(router: IRouterApi, services?: IServiceRegistry): void {
  registerSupportRoutes(router, services);
}
